mapper.select:
SELECT cc.id, srv.service_name AS serviceName, cc.course_class_code AS courseClassCode, cc.course_class_name AS courseClassName, cat.category_name AS categoryName, CASE WHEN cc.enroll_type = 3 AND IFNULL(JSON_LENGTH(cc.applicable_class_ids), 0) > 0 THEN grade_scope.resolved_grade_ids ELSE cc.applicable_grade_ids END AS applicableGradeIds, grade_scope.applicable_grade_names AS applicableGradeNames, cc.enroll_type AS enrollType, CASE cc.enroll_type WHEN 1 THEN '公开报名' WHEN 2 THEN '邀请报名' WHEN 3 THEN '行政班安排' ELSE '未知' END AS enrollTypeDesc, CONCAT(DATE_FORMAT(srv.course_start_date, '%Y-%m-%d'), '至', DATE_FORMAT(srv.course_end_date, '%Y-%m-%d')) AS courseCycle, t.teacher_name AS teacherName, cc.place_id AS placeId, cc.teacher_id, IFNULL(enrolled_count.student_count, 0) AS studentCount, IFNULL(att_rate.attendance_rate, 0.00) AS attendanceRate, te.term_name, srv.term_id AS termId FROM t_as_course_class cc INNER JOIN t_as_service srv ON cc.service_id = srv.id AND srv.is_valid = 1 INNER JOIN t_educl_term te ON te.id = srv.term_id AND te.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 LEFT JOIN t_as_teacher t ON cc.teacher_id = t.id AND t.is_valid = 1 LEFT JOIN ( SELECT ccg.id AS course_class_id, CONCAT( '[', GROUP_CONCAT(DISTINCT g.id ORDER BY g.sort_no, g.id SEPARATOR ','), ']' ) AS resolved_grade_ids, GROUP_CONCAT( DISTINCT g.grade_name ORDER BY g.sort_no, g.id SEPARATOR ',' ) AS applicable_grade_names FROM t_as_course_class ccg LEFT JOIN t_educl_grade g ON g.is_valid = 1 AND g.school_id = ccg.school_id AND ( ( ccg.enroll_type = 3 AND IFNULL(JSON_LENGTH(ccg.applicable_class_ids), 0) > 0 AND EXISTS ( SELECT 1 FROM t_educl_class ec_scope WHERE ec_scope.is_valid = 1 AND ec_scope.school_id = ccg.school_id AND ec_scope.grade_id = g.id AND JSON_CONTAINS( ccg.applicable_class_ids, CAST(ec_scope.id AS JSON) ) ) ) OR ( ccg.enroll_type IN (1, 2) AND JSON_CONTAINS( ccg.applicable_grade_ids, CAST(g.id AS JSON) ) ) OR ( ccg.enroll_type = 3 AND IFNULL(JSON_LENGTH(ccg.applicable_class_ids), 0) = 0 AND JSON_CONTAINS( ccg.applicable_grade_ids, CAST(g.id AS JSON) ) ) ) WHERE ccg.is_valid = 1 AND ccg.school_id = #{query.schoolId} GROUP BY ccg.id ) grade_scope ON cc.id = grade_scope.course_class_id LEFT JOIN ( SELECT e.course_class_id, COUNT(DISTINCT e.student_id) AS student_count FROM t_as_enrollment e INNER JOIN t_as_student stu ON e.student_id = stu.id AND stu.is_valid = 1 AND stu.register_status = 1 WHERE e.is_valid = 1 AND e.session_id IS NOT NULL AND e.enroll_status IN (1, 3) GROUP BY e.course_class_id ) enrolled_count ON cc.id = enrolled_count.course_class_id LEFT JOIN ( SELECT attendance_cc.id AS course_class_id, AS attendance_rate
GROUP BY attendance_cc.id ) att_rate ON cc.id = att_rate.course_class_id WHERE cc.is_valid = 1 AND cc.school_id = #{query.schoolId} AND srv.service_status IN (1, 2, 3)
AND cc.course_class_name LIKE CONCAT('%', #{query.courseClassName}, '%')
AND cc.category_id = #{query.categoryId}
AND cc.category_id IN
#{id}
AND cc.enroll_type = #{query.enrollType}
AND ( ( cc.enroll_type = 3 AND IFNULL(JSON_LENGTH(cc.applicable_class_ids), 0) > 0 AND EXISTS ( SELECT 1 FROM t_educl_class ec_filter WHERE ec_filter.is_valid = 1 AND ec_filter.school_id = cc.school_id AND ec_filter.grade_id = #{query.gradeId} AND JSON_CONTAINS( cc.applicable_class_ids, CAST(ec_filter.id AS JSON) ) ) ) OR ( cc.enroll_type IN (1, 2) AND JSON_CONTAINS( cc.applicable_grade_ids, CAST(#{query.gradeId} AS JSON) ) ) OR ( cc.enroll_type = 3 AND IFNULL(JSON_LENGTH(cc.applicable_class_ids), 0) = 0 AND JSON_CONTAINS( cc.applicable_grade_ids, CAST(#{query.gradeId} AS JSON) ) ) )
AND cc.teacher_id = #{query.teacherId}
AND srv.term_id = #{query.termId}
ORDER BY cc.course_class_name desc,cc.create_time DESC

SELECT cc.id AS id, cc.course_class_name AS courseClassName, cc.service_id AS serviceId FROM t_as_course_class cc INNER JOIN t_as_service srv ON cc.service_id = srv.id AND srv.is_valid = 1 WHERE cc.is_valid = 1 AND srv.course_end_date >= DATE(NOW())
AND EXISTS ( SELECT 1 FROM t_as_course_session cs_date WHERE cs_date.course_class_id = cc.id AND cs_date.is_valid = 1 AND DATE_FORMAT(cs_date.session_date, '%Y-%m-%d') = DATE_FORMAT(#{ao.currentDate}, '%Y-%m-%d') AND TIMESTAMP(cs_date.session_date, cs_date.start_time) <= NOW() )
AND EXISTS ( SELECT 1 FROM t_as_course_session cs WHERE cs.course_class_id = cc.id AND cs.is_valid = 1 AND TIMESTAMP(cs.session_date, cs.start_time) >= #{ao.startTime} AND TIMESTAMP(cs.session_date, cs.end_time) <= #{ao.endTime} )
AND cc.school_id = #{ao.schoolId}
AND cc.category_id IN
#{item}
AND (
(cc.enroll_type IN (1, 2)AND (
JSON_CONTAINS(cc.applicable_grade_ids,CAST(#{gid} AS JSON))
)) OR
(cc.enroll_type = 3 AND EXISTS (SELECT 1 FROM t_educl_class ec WHERE ec.is_valid = 1 AND ec.school_id = cc.school_id AND JSON_CONTAINS(cc.applicable_class_ids,CAST(ec.id AS JSON)) AND ec.grade_id IN
#{gid}
)))
AND cc.course_class_name LIKE CONCAT('%', #{ao.courseClassName}, '%')
AND cc.teacher_id = #{ao.teacherId}
ORDER BY cc.create_time DESC

SELECT COUNT(*) AS allCount, SUM(CASE WHEN cc.enroll_type = 1 THEN 1 ELSE 0 END) AS publicEnrollCount, SUM(CASE WHEN cc.enroll_type = 2 THEN 1 ELSE 0 END) AS inviteEnrollCount, SUM(CASE WHEN cc.enroll_type = 3 THEN 1 ELSE 0 END) AS adminArrangeCount FROM t_as_course_class cc INNER JOIN t_as_service srv ON cc.service_id = srv.id AND srv.is_valid = 1 WHERE cc.is_valid = 1 AND srv.service_status IN (1, 2, 3)
AND cc.school_id = #{query.schoolId}
AND srv.term_id = #{query.termId}

SELECT cc.id AS id, cc.course_class_name AS courseClassName, cc.service_id AS serviceId FROM t_as_course_class cc WHERE cc.is_valid = 1 AND cc.id IN
#{id}
AND EXISTS ( SELECT 1 FROM t_as_course_session cs_today WHERE cs_today.course_class_id = cc.id AND cs_today.is_valid = 1 AND DATE_FORMAT(cs_today.session_date, '%Y-%m-%d') = DATE_FORMAT(NOW(), '%Y-%m-%d') AND TIMESTAMP(cs_today.session_date, cs_today.start_time) <= NOW() ) ORDER BY cc.create_time DESC

SELECT DISTINCT stu.id AS studentId, gs.guardian_user_id AS userId FROM t_as_course_class cc INNER JOIN t_as_student_destination sd on sd.course_class_id = cc.id and sd.is_valid = 1 INNER JOIN t_as_student stu ON stu.id =sd.student_id and stu.register_status = 1 and stu.is_valid = 1 INNER JOIN t_as_guardian_student gs on gs.student_identity_id = stu.student_identity_id and gs.is_valid = 1 and bind_status = 1 WHERE cc.is_valid = 1 and cc.school_id = #{schoolId} and gs.guardian_user_id is not NULL AND cc.id IN
#{id}
AND stu.id IN
#{studentId}
